using int64 = long long;

static inline int64 floor_div(int64 a, int64 b) {
    // b > 0
    if (a >= 0) return a / b;
    return - ((-a + b - 1) / b);
}

static inline int64 ceil_div(int64 a, int64 b) {
    // b > 0
    if (a >= 0) return (a + b - 1) / b;
    return - ((-a) / b);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int64 X, Y, A, B, C;
        cin >> X >> Y >> A >> B >> C;

        A %= C;
        B %= C;

        // dp[i][j] = max good groups using i A-balls and j B-balls,
        // but we only need a formula.
        //
        // Let a group contain p A-balls and q B-balls.
        // It is good iff p*A + q*B ≡ 0 (mod C), with p+q >= 1.
        //
        // Since balls with same number are indistinguishable, maximizing number
        // of good groups is equivalent to choosing counts of good group types.
        //
        // Key observation:
        // - Pure A groups: need kA = C / gcd(A,C) A-balls each (unless A=0, then 1).
        // - Pure B groups: need kB similarly.
        // - Mixed groups can be represented by solutions of pA + qB ≡ 0 (mod C).
        //
        // The maximum can be found by considering how many A-balls and B-balls
        // are reserved for pure groups, and using the rest for mixed groups.
        //
        // For mixed groups, the maximum number equals the maximum t such that
        // there exist nonnegative integers p_i,q_i with sum p_i <= XA, sum q_i <= YB,
        // and each p_i A + q_i B ≡ 0 mod C.
        //
        // This simplifies to:
        // every good group contributes total residue 0, so total used balls must satisfy
        // u*A + v*B ≡ 0 (mod C).
        // If we want t groups, we need partition of u+v balls into t nonempty good groups.
        // This is possible iff there exists at least one good-group type, and
        // total used balls can be decomposed into t good groups.
        //
        // A cleaner route:
        // Any good group corresponds to a nonzero solution (p,q).
        // Let S be the set of such vectors. We want max sum z_s with
        // sum z_s*p_s <= X, sum z_s*q_s <= Y.
        //
        // In 2D ILP with one congruence, optimal solution uses at most one mixed type
        // plus pure types. So enumerate minimal mixed type.
        //
        // Minimal positive pure sizes:
        int64 kA = (A == 0 ? 1 : C / std::gcd<int64>(A, C));
        int64 kB = (B == 0 ? 1 : C / std::gcd<int64>(B, C));

        int64 ans = 0;

        // Pure groups only
        ans = max(ans, X / kA + Y / kB);

        // Enumerate minimal mixed groups by p in [0, C-1], solve for smallest q>=0.
        // Enough because residues repeat modulo C/g where g=gcd(B,C).
        // Complexity O(C), acceptable only if C small, but constraints are not given.
        // Need number-theoretic optimization.

        // Let's enumerate possible p up to period of A modulo C and derive minimal q.
        // To stay efficient, use the fact that any mixed group can be reduced to one
        // with p < C/gcd(A,C) or q < C/gcd(B,C). We enumerate the smaller side.
        int64 limA = (A == 0 ? 1 : C / gcd<int64>(A, C));
        int64 limB = (B == 0 ? 1 : C / gcd<int64>(B, C));

        auto mod_inv = [&](int64 a, int64 mod) -> int64 {
            int64 b = mod, u = 1, v = 0;
            while (b) {
                int64 t = a / b;
                a -= t * b; swap(a, b);
                u -= t * v; swap(u, v);
            }
            u %= mod;
            if (u < 0) u += mod;
            return u;
        };

        // Try enumerating smaller period to find candidate mixed types.
        if (A != 0 && B != 0) {
            if (limA <= limB) {
                int64 g = gcd<int64>(B, C);
                int64 B2 = B / g, C2 = C / g;
                int64 invB2 = mod_inv(B2 % C2, C2);

                for (int64 p = 1; p < limA; ++p) {
                    int64 rhs = (-p * A) % C;
                    if (rhs < 0) rhs += C;
                    if (rhs % g != 0) continue;
                    int64 q0 = ((rhs / g) % C2) * invB2 % C2;
                    if (q0 == 0) continue; // not mixed
                    // Use this mixed type (p,q0), plus pure groups on leftovers
                    int64 t = min(X / p, Y / q0);
                    // Candidates near maximum t are enough since objective linear in leftovers
                    for (int d = 0; d <= 2; ++d) {
                        if (t < d) break;
                        int64 use = t - d;
                        int64 cur = use;
                        cur += (X - use * p) / kA;
                        cur += (Y - use * q0) / kB;
                        ans = max(ans, cur);
                    }
                }
            } else {
                int64 g = gcd<int64>(A, C);
                int64 A2 = A / g, C2 = C / g;
                int64 invA2 = mod_inv(A2 % C2, C2);

                for (int64 q = 1; q < limB; ++q) {
                    int64 rhs = (-q * B) % C;
                    if (rhs < 0) rhs += C;
                    if (rhs % g != 0) continue;
                    int64 p0 = ((rhs / g) % C2) * invA2 % C2;
                    if (p0 == 0) continue; // not mixed
                    int64 t = min(X / p0, Y / q);
                    for (int d = 0; d <= 2; ++d) {
                        if (t < d) break;
                        int64 use = t - d;
                        int64 cur = use;
                        cur += (X - use * p0) / kA;
                        cur += (Y - use * q) / kB;
                        ans = max(ans, cur);
                    }
                }
            }
        }

        cout << ans << '\n';
    }
    return 0;
}

