                long total = X * A + Y * B;
                ans += total / C;
            }

            System.out.println(ans);
        }
        sc.close();
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
