import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return Math.abs(a);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        int T = fs.nextInt();
        while (T-- > 0) {
            long X = fs.nextLong();
            long Y = fs.nextLong();
            long A = fs.nextLong();
            long B = fs.nextLong();
            long C = fs.nextLong();

            long a = ((A % C) + C) % C;
            long b = ((B % C) + C) % C;

            long ans = 0;

            // Groups using only A balls
            if (a == 0) {
                ans += X;
                X = 0;
            }

            // Groups using only B balls
            if (b == 0) {
                ans += Y;
                Y = 0;
            }

            // Now a,b != 0 modulo C for remaining balls
            if (X == 0 || Y == 0) {
                out.append(ans).append('\n');
                continue;
            }

            long g = gcd(a, C);
            long needA = C / g; // smallest k>0 such that k*a ≡ 0 (mod C)

            g = gcd(b, C);
            long needB = C / g; // smallest k>0 such that k*b ≡ 0 (mod C)

            // Additional pure groups
            ans += X / needA;
            X %= needA;

            ans += Y / needB;
            Y %= needB;

            // Mixed groups:
            // Need i*a + j*b ≡ 0 (mod C), i,j >= 1.
            // Since X < needA and Y < needB now, brute force over smaller side.
            long best = 0;

            // Enumerate possible count of A in one mixed group
            for (long i = 1; i <= X; i++) {
                long rem = (C - (i * a) % C) % C;

                long gg = gcd(b, C);
                if (rem % gg != 0) continue;

                long c2 = C / gg;
                long bb = b / gg;
                long rr = rem / gg;

                long inv = modInverse(bb % c2, c2);
                long j0 = (rr % c2) * inv % c2;
                if (j0 == 0) j0 = c2; // need positive j

                if (j0 <= Y) {
                    long groups = Math.min(X / i, Y / j0);
                    if (groups > best) best = groups;
                }
            }

            // Enumerate possible count of B in one mixed group
            for (long j = 1; j <= Y; j++) {
                long rem = (C - (j * b) % C) % C;

                long gg = gcd(a, C);
                if (rem % gg != 0) continue;

                long c2 = C / gg;
                long aa = a / gg;
                long rr = rem / gg;

                long inv = modInverse(aa % c2, c2);
                long i0 = (rr % c2) * inv % c2;
                if (i0 == 0) i0 = c2; // need positive i

                if (i0 <= X) {
                    long groups = Math.min(X / i0, Y / j);
                    if (groups > best) best = groups;
                }
            }

            ans += best;
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    static long modInverse(long a, long mod) {
        long[] res = extGcd(a, mod);
        long x = res[0];
        x %= mod;
        if (x < 0) x += mod;
        return x;
    }

    static long[] extGcd(long a, long b) {
        if (b == 0) return new long[]{1, 0, a};
        long[] t = extGcd(b, a % b);
        long x = t[1];
        long y = t[0] - (a / b) * t[1];
        return new long[]{x, y, t[2]};
    }
}

import sys
from math import gcd

def solve():
    X, Y, A, B, C = map(int, input().split())

    best = 0
    # Try all combinations of a A-balls and b B-balls in a good group
    # a ranges 0..C, b ranges 0..C (by pigeonhole, we only need up to C of each)
    for a in range(C + 1):
        for b in range(C + 1):
            if a == 0 and b == 0:
                continue
            if (a * A + b * B) % C == 0:
                if a <= X and b <= Y:
                    # How many such groups can we form?
                    groups = min(X // a if a > 0 else float('inf'),
                                 Y // b if b > 0 else float('inf'))
                    best = max(best, groups)

    print(best)

T = int(input())
for _ in range(T):
    solve()
